'use strict';

// MODULES //

var tape = require( 'tape' );
var contains = require( '@stdlib/assert/contains' );
var rule = require( './../lib' );


// TESTS //

tape( 'main export is a function', function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof rule, 'function', 'main export is a function' );
	t.end();
});

tape( 'the function returns `[ true, \'\' ]` when the `when` parameter is `never`', function test( t ) {
	var result = rule({
		'subject': 'add math/base/special/abs'
	}, 'never' );
	t.deepEqual( result, [ true, '' ], 'returns expected value' );
	t.end();
});

tape( 'the function returns `[ true, \'\' ]` for valid messages with backtick-wrapped package references', function test( t ) {
	var subjects;
	var result;
	var i;

	subjects = [
		'feat: add `math/base/special/abs`',
		'docs: update `stats/maxabs`',
		'fix: resolve issue in `blas/base/dasum`',
		'feat: add `constants/float16/nan`',
		'docs: update `dists/chi/logpdf`',
		'feat: add `math/base/special/abs` and `math/base/special/sin`'
	];
	for ( i = 0; i < subjects.length; i++ ) {
		result = rule({
			'subject': subjects[ i ]
		}, 'always' );
		t.deepEqual( result, [ true, '' ], 'returns expected value' );
	}
	t.end();
});

tape( 'the function returns `[ true, \'\' ]` for messages without package references', function test( t ) {
	var subjects;
	var result;
	var i;

	subjects = [
		'docs: fix typo in README',
		'chore: update dependencies',
		'fix: resolve memory leak',
		'feat: add new feature',
		'docs: see http://example.com/foo/bar/baz'
	];
	for ( i = 0; i < subjects.length; i++ ) {
		result = rule({
			'subject': subjects[ i ]
		}, 'always' );
		t.deepEqual( result, [ true, '' ], 'returns expected value' );
	}
	t.end();
});

tape( 'the function returns `[ false, ... ]` for messages with unquoted package references', function test( t ) {
	var subjects;
	var result;
	var i;

	subjects = [
		'feat: add math/base/special/abs',
		'docs: update stats/maxabs',
		'feat: add dists/chi/logpdf',
		'fix: update base/special/abs',
		'docs: fix special/abs'
	];
	for ( i = 0; i < subjects.length; i++ ) {
		result = rule({
			'subject': subjects[ i ]
		}, 'always' );
		t.strictEqual( result[ 0 ], false, 'returns expected value' );
	}
	t.end();
});

tape( 'the function returns `[ false, ... ]` for messages with `@stdlib/` prefix', function test( t ) {
	var result = rule({
		'subject': 'feat: add `@stdlib/math/base/special/abs`'
	}, 'always' );
	t.strictEqual( result[ 0 ], false, 'returns expected value' );
	t.ok( contains( result[ 1 ], '@stdlib/' ), 'returns expected value' );
	t.end();
});

tape( 'the function returns `[ false, ... ]` for messages with multiple errors', function test( t ) {
	var result = rule({
		'subject': 'feat: add math/base/special/abs and @stdlib/stats/base'
	}, 'always' );
	t.strictEqual( result[ 0 ], false, 'returns expected value' );
	t.end();
});

tape( 'the function returns `[ true, \'\' ]` for generic paths not starting with known namespaces', function test( t ) {
	var subjects;
	var result;
	var i;

	subjects = [
		'docs: update src/lib/utils',
		'fix: resolve issue in foo/bar/baz',
		'chore: update config/settings/main'
	];
	for ( i = 0; i < subjects.length; i++ ) {
		result = rule({
			'subject': subjects[ i ]
		}, 'always' );
		t.deepEqual( result, [ true, '' ], 'returns expected value' );
	}
	t.end();
});

tape( 'the function returns `[ true, \'\' ]` for URLs containing namespace-like paths', function test( t ) {
	var subjects;
	var result;
	var i;

	subjects = [
		'docs: see http://example.com/math/base/special',
		'docs: update https://github.com/stdlib-js/stdlib',
		'docs: link to ftp://files.example.com/stats/data'
	];
	for ( i = 0; i < subjects.length; i++ ) {
		result = rule({
			'subject': subjects[ i ]
		}, 'always' );
		t.deepEqual( result, [ true, '' ], 'returns expected value' );
	}
	t.end();
});

tape( 'the function returns `[ true, \'\' ]` for empty or missing subject', function test( t ) {
	var result;

	result = rule({
		'subject': ''
	}, 'always' );
	t.deepEqual( result, [ true, '' ], 'returns expected value' );

	result = rule( {}, 'always' );
	t.deepEqual( result, [ true, '' ], 'returns expected value' );
	t.end();
});
